function renderMaterialsPage({MODEL,$,fmt,n,esc,raw,unit,factBtn,sheetBtn,heading,moneyless,revisedQuantity,foundationBalanceCard,loadComparisonHTML,foundationRebarAuditCard,FACTS}){
 const register=MODEL.foundation.material_register;
 const foundationMaterials=register.rows.filter(row=>row.issued_quantity&&!row.id.startsWith('rebar-'));
 const accessoryMaterials=register.rows.filter(row=>!row.issued_quantity&&
  !['counted_plan_symbols','plan_reserve','reference_sleeve_section'].includes(row.model_scope));
 const steel=['foundation.Фм1.steel_kg_А240_8','foundation.Фм1.steel_kg_А500С_8','foundation.Фм1.steel_kg_А500С_12'];
 const rebarRows=Array.from({length:8},(_,i)=>{const ent='foundation.Фм1.rebar.'+(i+1),q=FACTS.get(ent+'.quantity');return `<tr><td class="number">${i+1}</td><td>Ø${raw(ent+'.diameter')} ${raw(ent+'.grade')}</td><td class="number">${FACTS.has(ent+'.length')?raw(ent+'.length'):'погонный расход'}</td><td class="number">${revisedQuantity(ent+'.quantity')}</td><td class="number">${raw(ent+'.unit_mass')} ${unit(FACTS.get(ent+'.unit_mass').unit)}</td><td>${factBtn(ent+'.quantity','КЖ-4')}</td></tr>`;}).join('');
 const geo=Object.fromEntries(MODEL.foundation.calculations.map(c=>[c.id.split('.').at(-1),Number(c.value)]));
 const takeoff=MODEL.foundation.steel_takeoff,concrete=geo.total_volume,blinding=geo.blinding;
 const mesh=register.mesh_crossings;
 const equivalents=Object.fromEntries(register.issued_layer_equivalents.map(row=>[row.id,row.area_m2]));
 $('page-materials').innerHTML=heading('02 / ФУНДАМЕНТ / РАСЧЁТНЫЙ ВАРИАНТ','Материалы фундамента без дуги','Количество по модели с прямым восточным краем. Расчётные объёмы показаны без закупочного запаса.','По новой геометрии')+
 `<p><button data-material-ledger="foundation">Сводная ведомость материалов</button> <button data-passage-coordination>Сдвиг гильз К1</button></p><div class="metric-grid">${[['БЕТОН В25',concrete,'м³','Плита и ростверки'],['ПОДГОТОВКА В10',blinding,'м³','В пределах плиты'],['АРМАТУРА',takeoff.net_mass_kg,'кг','Оценка по базовой раскладке'],['ПЛОЩАДЬ ПЛИТЫ',geo.area,'м²','Край параллельно фасаду']].map(([label,val,u,note])=>`<div class="metric"><div class="eyebrow">${label}</div><strong>${fmt(val,3)} <em>${u}</em></strong><small>${note}</small></div>`).join('')}</div>
 <div class="section-grid"><div class="card" id="foundation-accessory-materials"><h3>Гидроизоляция и сопутствующие материалы</h3><div class="table-wrap"><table><thead><tr><th>Материал</th><th>Расчёт</th><th>Источник</th></tr></thead><tbody>${accessoryMaterials.map(row=>`<tr data-material="${esc(row.id)}"><td>${esc(row.label)}<small class="block-note">${esc(row.application)}</small></td><td>${row.model_quantity===null?'Уточняется':fmt(row.model_quantity,8)+' '+unit(row.unit)}<small class="block-note">${esc(row.explanation)}</small></td><td>${factBtn(row.source_fact_ids[0])}</td></tr>`).join('')}</tbody></table></div>
 <p>В базовой раскладке по ${fmt(mesh.lower)} пересечений в плане нижней сетки и ${fmt(mesh.upper)} в верхней. Расход проволоки зависит от схемы вязки.</p>
 <div class="buttons-row"><button data-foundation-waterproofing>Обмер вертикальных граней</button><button data-sleeve-review>Ведомость гильз</button><button data-foundation-passages>Вырезы в бетоне и полотнищах</button>${sheetBtn('house_2',8,'КЖ-3 · сечения')}</div></div>
 <div class="card"><h3>Арматура по новой форме</h3><table><thead><tr><th>Поз.</th><th>Раскладка</th><th>Масса, кг</th></tr></thead><tbody>${takeoff.rows.map(r=>`<tr><td>${r.position}</td><td>${fmt(r.quantity,3)} ${unit(r.unit)}</td><td>${fmt(r.net_mass_kg,3)}</td></tr>`).join('')}</tbody></table><p>${esc(takeoff.note)}</p><button data-mesh-seat-study>Посадка фиксатора</button> <button data-fm1-splice-study>Нахлёсты и раскрой</button> <button data-edge-link-study>Краевые хомуты</button> <button data-beam-starter-study>Стержни ростверка</button> <button data-beam-pin-study>Шпильки ростверка</button> <button data-beam-longitudinal-study>Продольные стержни</button> <button data-edge-mesh-study>Край сетки · 150 мм</button></div></div>
 <div class="section-grid"><div><div class="card" id="foundation-material-quantities"><h3>Материалы КЖ-4</h3><div class="table-wrap"><table><thead><tr><th>Материал</th><th>Исходная ведомость</th><th>Расчёт по модели</th></tr></thead><tbody>${foundationMaterials.map(row=>{
  const units=unit(row.unit),source=row.issued_quantity.fact_id;
  const scope=row.model_scope==='slab_footprint'?'<small class="block-note">В пятне плиты</small>':'';
  const estimate=row.scenario_input?'<button data-foundation-apron>Три варианта XPS</button>':
   row.model_quantity===null?'По отдельной раскладке':fmt(row.model_quantity,8)+' '+units;
  return `<tr><td>${esc(row.label)}</td><td class="number">${factBtn(source,FACTS.get(source).raw_value+' '+units)}</td><td class="number">${estimate}${scope}</td></tr>`;
 }).join('')}</tbody></table></div><p>В КЖ-4 объём В10 соответствует ${fmt(equivalents.blinding)} м² при толщине 50 мм, а объём каждой фракции щебня — ${fmt(equivalents.gravel_5_10)} м² при толщине 200 мм. Границы этих площадей и выносы под отмостку требуют уточнения.</p><p>${esc(foundationMaterials.find(row=>row.id==='xps').explanation)}</p><button data-foundation-base>Обмер основания</button> ${sheetBtn('house_2',9,'КЖ-4','revision')}</div>
 <div class="card"><h3>Сталь Фм 1 · с надбавкой 5 %</h3><table><thead><tr><th>Арматура</th><th>Масса</th><th>Источник</th></tr></thead><tbody>${steel.map((id,i)=>`<tr><td>${['А240 · Ø8','А500С · Ø8','А500С · Ø12'][i]}</td><td class="number">${revisedQuantity(id)}</td><td>${factBtn(id)}</td></tr>`).join('')}<tr><td><b>Всего</b></td><td class="number">${revisedQuantity('foundation.Фм1.steel_kg_total')}</td><td>${factBtn('foundation.Фм1.steel_kg_total')}</td></tr></tbody></table><div class="formula">${fmt(takeoff.net_mass_kg)} × 1,05 = ${fmt(MODEL.foundation.quantity_changes['foundation.Фм1.steel_kg_total'].current)} кг</div><p>Зачёркнуты итоги исходной ведомости с её надбавкой 5 %. Новые массы получены из текущих длин и количества деталей с той же надбавкой.</p></div></div>
 <div><div class="card"><h3>Бетон и цемент — разные количества</h3><p>Для нового контура учтены ${fmt(concrete)} м³ В25 и ${fmt(blinding)} м³ В10 в пятне плиты. Расход цемента на м³ смеси в этих листах не найден. Без рецептуры нельзя перевести это в точное количество мешков.</p><div class="callout"><b>Расход цемента по проекту не определён</b>Нужны составы В25 W6 F150 и В10. Калькулятор ниже считает только введённый сценарий; справочных норм по умолчанию нет.</div><div class="input-grid"><label>В25: цемент, кг/м³<input id="cement-b25" type="number" min="0" max="1000" step="0.1" placeholder="из рецептуры"></label><label>В10: цемент, кг/м³<input id="cement-b10" type="number" min="0" max="1000" step="0.1" placeholder="из рецептуры"></label></div><div class="calc-result" id="cement-result">Не задано<small>Проектный расход цемента отсутствует.</small></div><div class="formula">m = ${fmt(concrete)} × C<sub>В25</sub> + ${fmt(blinding)} × C<sub>В10</sub>, кг</div></div>
 <div class="card" id="porch-materials"><h3>Крыльца Крм 1 и Крм 2</h3><p>Крм 1 восстановлено по КЖ-5. Количество изделий и материалов входного крыльца приведено по КЖ-6.</p><table><thead><tr><th>Элемент</th><th>В25</th><th>Сталь</th></tr></thead><tbody>${[1,2].map(i=>{
  const id=`porch.Крм${i}`;
  return `<tr><td>${factBtn(id+'.concrete.quantity','Крм '+i)}</td><td class="number">${revisedQuantity(id+'.concrete.quantity')}</td><td class="number">${revisedQuantity(id+'.steel_kg_total')}</td></tr>`;
 }).join('')}</tbody></table>${sheetBtn('house_2',10,'КЖ-5','revision')} ${sheetBtn('house_2',11,'КЖ-6','revision')}</div>
 <div class="card"><h3>Плита и ростверки Фм 1</h3><div class="formula"><del>246,4 × 0,300 = 73,92 м³</del><br><strong class="updated">${fmt(geo.area)} × 0,300 = ${fmt(geo.slab_volume,8)} м³</strong><br>Ростверки над плитой · ${fmt(geo.plinth_volume,8)} м³<br>Всего В25 · ${revisedQuantity('foundation.concrete.quantity')}</div><p>Покрытие входной площадки № 12 в плане · ${revisedQuantity('building.terrace_porch_area')}. Восточная терраса снята. Для заказа плитки требуется раскладка.</p>${sheetBtn('house_1',8,'АР-7 · экспликация площадок')}</div></div></div>
 <div class="card"><div class="page-heading"><div><h3>Восемь позиций КЖ-4 · пересчёт количества</h3><p>Погонные метры и штуки сохранены разными единицами. Длина — заготовка из спецификации.</p></div></div><div class="table-wrap"><table><thead><tr><th>Поз.</th><th>Диаметр / класс</th><th>Длина, мм</th><th>Количество</th><th>Масса единицы</th><th>Источник</th></tr></thead><tbody>${rebarRows}</tbody></table></div>${sheetBtn('house_2',9,'КЖ-4 · исходная ведомость и формы деталей')}</div>`;
 const recalc=()=>{const a=$('cement-b25'),b=$('cement-b10');if(a.value===''||b.value===''||!a.validity.valid||!b.validity.valid){$('cement-result').innerHTML='Не задано<small>Введите обе дозировки из рецептур.</small>';return;}const result=concrete*+a.value+blinding*+b.value;$('cement-result').innerHTML=`${fmt(result,3)} кг<small>Сценарий пользователя · не проектный расход. Только Фм 1 и подготовка, без Крм 1/2.</small>`;};$('page-materials').querySelector('.metric-grid').insertAdjacentHTML('afterend',foundationBalanceCard()+loadComparisonHTML());$('cement-b25').oninput=recalc;$('cement-b10').oninput=recalc;
 $('page-materials').insertAdjacentHTML('beforeend',foundationRebarAuditCard());
}

export { renderMaterialsPage };
